const nav=[['inbox','구매요청 업무함'],['procurement','CSV · 자동 감지 · 견적'],['inventory','원료 · Lot 재고'],['production','생산 · 납기 계획'],['suppliers','공급업체 · 견적'],['orders','발주서 · ERP 등록'],['tracking','출하 · 입고 · 품질'],['audit','승인 · 업무 이력'],['connected','통합 서버 · 실제 AI'],['settings','기준 · 시연 설정']] as const;
