function quoteRequestBody(workflow:Workflow,vendorName:string){const d=workflow.data,required=risk(workflow).required;const buffer=d.config.qcDays+d.config.qaDays;const lines=d.productions.map(p=>`- ${p.id}: ${p.date} 투입 / ${p.il7}${d.products[0].unit} / 희망 입고일 ${addDays(p.date,-buffer)}까지`).join('\n');return `${vendorName} 담당자님께,\n\n안녕하세요. BioFlow 구매 담당자입니다. 아래 원료의 견적 및 공급 가능 조건을 요청드립니다.\n\n구매요청번호: ${CASE}\n원료: ${d.products[0].name} (${d.products[0].id} / ${d.products[0].sku})\n요청수량: 총 ${required}${d.products[0].unit} (생산 투입 수량 기준)\n생산별 필요 일정:\n${lines}\n\n아래 조건을 회신 부탁드립니다.\n1. 바이알 단가, MOQ, 주문 배수, 운송비\n2. 생산별 수량의 분할 납품 가능 여부와 회차별 확약 입고일\n3. 제조사·제품 규격, Lot별 유효기간, CoA 및 운송 품질 문서\n4. 지급 조건, 견적 유효기간, 납기 변경·취소 조건\n\nQC ${d.config.qcDays}일 및 QA ${d.config.qaDays}일의 검토 기간을 고려해 희망 입고일을 확인해 주세요. 회신 양식 CSV를 첨부합니다.\n\n감사합니다.\nBioFlow 구매팀\n\n※ 요청 내용은 ERP에 등록된 현재 데이터에서 생성됩니다. 발송 전 원료 규격·수량·일정이 실제 구매 요청과 일치하는지 확인해 주세요.`}
function Status({children,tone='normal'}:{children:ReactNode;tone?:string}){return <span className={'wf-status '+tone}>{children}</span>}
function DecisionModal({open,title,onClose,children}:{open:boolean;title:string;onClose:()=>void;children:ReactNode}){return <Dialog.Root open={open} onOpenChange={v=>!v&&onClose()}><Dialog.Portal><Dialog.Overlay className="wf-modal-overlay"/><Dialog.Content className="wf-modal"><header><Dialog.Title>{title}</Dialog.Title><Dialog.Close aria-label="닫기"><X size={20}/></Dialog.Close></header><Dialog.Description className="sr-only">의사결정 전에 데이터와 승인 범위를 확인하세요.</Dialog.Description><div className="wf-modal-body">{children}</div></Dialog.Content></Dialog.Portal></Dialog.Root>}
const fields:Record<string,string>={quantity:'재고/확약 수량',expiry:'유효일',date:'원료 투입일',delivery:'고객 납기',il7:'IL-7 필요량',unitPrice:'바이알 단가(원)',moq:'MOQ',multiple:'주문배수',shipping:'회차 운송비(원)',arrival:'입고 처리 완료일',qcDelay:'QC 시작 대기(일)',cashLimit:'지급일 현금 한도(원)',budget:'통합 구매예산(원)',qcDays:'QC 시험 일수',qaDays:'QA 검토 일수'};
const dateKeys=new Set(['expiry','date','delivery','arrival']);
export default function FlowApp({onPrevious}:{onPrevious:()=>void}){
 const [serverEnabled,setServerConnected]=useState(isServerEnabled);const [approving,setApproving]=useState(false);
 const [s,setS]=useState(loadFlow);const [page,setPage]=useState<Page>('inbox');const [tab,setTab]=useState<Tab>('overview');const [modal,setModal]=useState<Modal>(null);const [drawer,setDrawer]=useState<Drawer>(null);const [toast,setToast]=useState('');const [edit,setEdit]=useState<Edit|null>(null);const [error,setError]=useState('');
 const [analysisTable,setAnalysisTable]=useState<TableKind|'inquiries'>('lots');const [running,setRunning]=useState(false);const [processing,setProcessing]=useState<'replies'|'orchestrator'|null>(null);const [speed,setSpeed]=useState(1300);const [replyMode,setReplyMode]=useState<ReplyMode>('normal');const [selectedPO,setSelectedPO]=useState('');const [selectedLine,setSelectedLine]=useState('');const [displayCandidate,setDisplayCandidate]=useState('B');const [analysisError,setAnalysisError]=useState('');
 const [mailSettings,setMailSettings]=useState<MailSettings|null>(null);const [mailForm,setMailForm]=useState<EmailForm|null>(null);const [mailOutbox,setMailOutbox]=useState<Record<string,unknown>[]>([]);const [mailSending,setMailSending]=useState(false);const [mailConfirmed,setMailConfirmed]=useState(false);const [mailSentId,setMailSentId]=useState('');const [mailIdempotencyKey,setMailIdempotencyKey]=useState('');const [mailError,setMailError]=useState('');const [mailPassword,setMailPassword]=useState('');const [mailConnecting,setMailConnecting]=useState(false);
 const sRef=useRef(s);sRef.current=s;
 const r=useMemo(()=>risk(s),[s]);const a=useMemo(()=>analyze(effectiveData(s)),[s]);const approved=inquiryApprovalValid(s);const stamp=workflowStamp(s);const findings=s.findings.filter(f=>f.stamp===stamp);const report=s.integration;const stale=!!report&&(report.stamp!==stamp||report.revision!==s.data.revision);const order=s.orders.find(o=>o.id===selectedPO)||s.orders[0];const poLine=order?.lines.find(l=>l.id===selectedLine)||order?.lines[1]||order?.lines[0];const activeAgent=running?agents.find(agent=>!findings.some(f=>f.agent===agent.id)):undefined;const orchestratorActive=running&&!activeAgent;const analysisProgress=findings.length+(report&&!stale?1:0);
 const analysisIssues=analysisBlockers(s);
 const repliesProcessed=s.inquiries.length>0&&s.inquiries.every(q=>q.status!=='요청중');const stage=s.orders.length?7:report&&!stale?5:findings.length===4?4:findings.length||repliesProcessed?3:s.inquiries.length?2:approved?2:s.approvals[0]?.kind===1?1:0;
 useEffect(()=>{setS(prev=>detect(prev));},[s.data.revision,s.now,s.orders.length,s.produced.join('|')]);
 useEffect(()=>{if(!s.approvals.length&&!s.deferred&&!s.orders.length&&r.level!=='정상'){const id=setTimeout(()=>setModal('risk'),650);return()=>clearTimeout(id)}},[]);
 useEffect(()=>{if(!saveFlow(s))setToast('저장 공간이 부족합니다. 현재 세션의 상태는 유지됩니다.')},[s]);
 useEffect(()=>{if(modal!=='mail'&&modal!=='mail-settings')setMailPassword('')},[modal]);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),4200);return()=>clearTimeout(t)},[toast]);
 useEffect(()=>{setAnalysisError('')},[stamp]);
 useEffect(()=>{if(!running)return;const pending=agents.find(agent=>!findings.some(f=>f.agent===agent.id));const delay=pending?pending.id==='inventory'?speed*1.4:pending.id==='purchase'?speed*.55:pending.id==='quality'?speed*1.1:speed*1.65:speed*1.9;const t=setTimeout(()=>{try{setS(pending?runAgent(s,pending.id):s.extraRequests.some(q=>!q.resolved)?extraAnalyze(s):integrate(s))}catch(e){setAnalysisError((e as Error).message);setToast((e as Error).message);setRunning(false);}if(!pending)setRunning(false)},delay);return()=>clearTimeout(t)},[running,s,findings.length,speed]);
 useEffect(()=>{const f=findings.at(-1);if(f)setAnalysisTable(f.agent==='inventory'?'lots':f.agent==='purchase'?'inquiries':f.agent==='quality'?'shipments':'costs')},[findings.at(-1)?.id]);
 useEffect(()=>{if(order&&!selectedPO)setSelectedPO(order.id)},[order,selectedPO]);
 
 // Execute actions before enqueueing React updates so validation errors remain in this boundary.
 function apply(fn:(x:Workflow)=>Workflow,message?:string){try{const next=fn(s);setS(next);if(message)setToast(message);return next}catch(e){setToast((e as Error).message);return null}}
 function go(p:Page){setPage(p);setDrawer(null);window.scrollTo({top:0,behavior:'smooth'})}
 function openCase(next:Tab='overview'){setPage('case');setTab(next);setDrawer(null);window.scrollTo({top:0,behavior:'smooth'})}
 function beginAnalysis(){const issues=analysisBlockers(s);if(issues.length){setAnalysisError(issues[0]);setRunning(false);if(!approved)setModal('first');else{setPage('case');setTab('inquiries')}return}setAnalysisError('');setS({...s,findings:[],extraRequests:[],integration:null});setTab('analysis');setRunning(true);setPage('case');}
 function analyzeAll(){const issues=analysisBlockers(s);if(issues.length){setAnalysisError(issues[0]);return}let current=s;setAnalysisError('');try{for(const agent of agents)current=runAgent(current,agent.id);current=integrate(current);if(current.extraRequests.some(q=>!q.resolved))current=extraAnalyze(current);setS(current);setRunning(false);setToast('4개 독립 분석과 Orchestrator 추가 검증을 모두 실행했습니다.')}catch(e){setAnalysisError((e as Error).message);setToast((e as Error).message)}}

 async function approveFinal(){setApproving(true);try{let next:Workflow;if(serverEnabled){await saveWorkspace(s);const remote=await serverCommand('registerPO');if(!remote.workflow)throw Error('서버 발주 등록 실패');next=remote.workflow;setS(next);setToast('서버 계산·권한·버전 검증 및 DB 발주 등록 완료');}else{next=registerPO(s);setS(next);setToast('2차 승인 및 로컬 가상 PO 등록 완료');}setModal(null);setSelectedPO(next.orders[0].id);setDrawer({type:'po',po:next.orders[0]});setPage('orders');}catch(e){setToast((e as Error).message)}finally{setApproving(false)}}
 function editRow(kind:TableKind|'config',row:Row){let obj:Record<string,unknown>={},keys:string[]=[];if(kind==='lots'){obj={...s.data.lots.find(l=>l.id===row.id)!};keys=['quantity','expiry']}if(kind==='quotes'){obj={...s.data.vendors.find(v=>v.id===row.id)!};keys=['unitPrice','moq','multiple','shipping']}if(kind==='production'){obj={...s.data.productions.find(p=>p.id===row.id)!};keys=['date','delivery','il7']}if(kind==='shipments'){obj={...s.data.vendors.flatMap(v=>v.shipments).find(l=>l.id===row.id)!};keys=['arrival','qcDelay','quantity','cashLimit']}if(kind==='config'){obj={...s.data.config};keys=['budget','qcDays','qaDays']}setEdit({kind,id:row.id,values:Object.fromEntries(keys.map(k=>[k,String(obj[k])]))});setError('')}
 function submitEdit(){if(!edit)return;const d=structuredClone(s.data),values:Record<string,string|number>={};for(const [k,v] of Object.entries(edit.values)){if(!v.trim()){setError('모든 필드를 입력하세요.');return}values[k]=dateKeys.has(k)?v:Number(v)}if(edit.kind==='lots')Object.assign(d.lots.find(l=>l.id===edit.id)!,values);if(edit.kind==='quotes')Object.assign(d.vendors.find(v=>v.id===edit.id)!,values);if(edit.kind==='shipments')Object.assign(d.vendors.flatMap(v=>v.shipments).find(l=>l.id===edit.id)!,values);if(edit.kind==='production'){const p=d.productions.find(p=>p.id===edit.id)!;Object.assign(p,values);p.completion=addDays(p.date,5)}if(edit.kind==='config')Object.assign(d.config,values);try{setS(editData(s,d,edit.id,JSON.stringify(values)));setEdit(null);setRunning(false);setModal('change')}catch(e){setError((e as Error).message)}}
 async function refreshMailSettings(){const config=apiRecord(await serverApi('/mail/settings')) as unknown as MailSettings;setMailSettings(config);setMailForm(current=>current?{...current,sender_email:current.sender_email||config.default_sender,recipient_email:current.recipient_email||config.default_recipient}:current);return config;}
 async function openMailSettings(){setMailForm(null);setMailSentId('');setMailPassword('');setMailError('');setModal('mail-settings');try{await refreshMailSettings()}catch(e){setMailSettings(null);setMailError((e as Error).message+' · 승인자 계정으로 연결해 주세요.')}}
 async function connectMailApprover(){setMailConnecting(true);setMailError('');try{await loginLocal();setServerConnected(true);await refreshMailSettings();setMailOutbox(apiRows(await serverApi(`/mail/outbox?case_id=${encodeURIComponent(CASE)}`)))}catch(e){setMailError((e as Error).message+' · 통합 서버 탭에서 승인자 계정으로 로그인해 주세요.')}finally{setMailConnecting(false)}}
 async function connectGmail(e:FormEvent<HTMLFormElement>){e.preventDefault();if(mailConnecting)return;setMailConnecting(true);setMailError('');try{const config=apiRecord(await serverSend('/mail/connect',{app_password:mailPassword})) as unknown as MailSettings;setMailSettings(config);setToast('Gmail 인증을 확인했습니다. 견적 요청 메일을 발송할 수 있습니다.')}catch(e){setMailError((e as Error).message)}finally{setMailPassword('');setMailConnecting(false)}}
 async function openQuoteComposer(){if(!approved){setModal('first');return}if(!s.inquiries.length){setToast('공급 확인 요청을 먼저 생성하세요.');return}if(!mailEligibleVendors.length){setToast('실제 메일 요청 대기 업체가 없습니다. 이미 처리된 가상 회신을 실제 요청으로 변경할 수 없습니다.');return}const vendor=mailEligibleVendors.find(v=>v.id==='B')||mailEligibleVendors[0];setMailForm({vendor_id:vendor.id,vendor_name:vendor.name,sender_email:mailSettings?.default_sender||'',recipient_email:mailSettings?.default_recipient||'',subject:`견적 요청: ${s.data.products[0].id} · ${CASE}`,body:quoteRequestBody(s,vendor.name)});setMailConfirmed(false);setMailSentId('');setMailPassword('');setMailIdempotencyKey(`bioflow-${crypto.randomUUID()}`);setMailError('');setModal('mail');try{await refreshMailSettings()}catch(e){const status=Number((e as {status?:number}).status||0);setMailError(status===401||status===403?'메일 설정을 불러오려면 승인자 계정으로 연결해 주세요.':(e as Error).message)}try{setMailOutbox(apiRows(await serverApi(`/mail/outbox?case_id=${encodeURIComponent(CASE)}`)))}catch{/* Outbox requires an approver session. */}}

 async function sendQuoteEmail(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!mailForm||!mailSettings?.configured||!mailConfirmed||mailSending||mailSentId)return;if(!canSendQuote(sRef.current.inquiries.find(q=>q.vendor===mailForm.vendor_id))){setMailError('해당 업체의 요청이 이미 가상 회신 처리됐습니다. 실제 메일을 보내지 않았습니다.');return}setMailSending(true);setMailError('');try{const remote=await saveWorkspace(sRef.current);const payload={...quoteDraft(sRef.current,mailForm.vendor_id),...mailForm,expected_revision:remote.revision,source_stamp:remote.stamp,final_confirmation:true,delivery_mode:'smtp'};const result=apiRecord(await serverSend('/mail/quote-requests',payload,'POST',{'Idempotency-Key':mailIdempotencyKey}));const entry={id:result.id,vendor_id:mailForm.vendor_id,vendor_name:mailForm.vendor_name,sender:mailForm.sender_email,recipient:mailForm.recipient_email,subject:mailForm.subject,status:result.status,message_id:result.message_id,created_at:result.created_at};setMailOutbox(current=>[entry,...current.filter(row=>row.id!==entry.id)]);try{const key=`bioflow-sent-vendors:${CASE}`;const ids=JSON.parse(localStorage.getItem(key)||'[]') as string[];localStorage.setItem(key,JSON.stringify([...new Set([...ids,mailForm.vendor_id])]))}catch{}setS(recordExternalMailSent(sRef.current,mailForm.vendor_id,String(result.message_id||result.id)));setMailSentId(String(result.id));setMailConfirmed(false);setToast(`${mailForm.vendor_name}에 견적 요청 메일을 실제 발송했습니다. 업체 회신은 자동 수신되지 않습니다.`)}catch(err){const status=Number((err as {status?:number}).status||0);setMailError(status===401||status===403?'실제 발송은 승인자 로그인이 필요합니다. 통합 서버 · 실제 AI 탭에서 승인자로 연결한 뒤 다시 시도하세요.':(err as Error).message)}finally{setMailSending(false)}}
 async function receive(){if(processing)return;setProcessing('replies');await new Promise(resolve=>window.setTimeout(resolve,1250));try{let persisted:Record<string,unknown>[]=[];try{persisted=apiRows(await serverApi(`/mail/outbox?case_id=${encodeURIComponent(CASE)}`));setMailOutbox(current=>[...persisted,...current.filter(row=>!persisted.some(saved=>saved.id===row.id))])}catch{}let localSent:string[]=[];try{localSent=JSON.parse(localStorage.getItem(`bioflow-sent-vendors:${CASE}`)||'[]')}catch{}const externallySent=[...new Set([...mailOutbox,...persisted].filter(row=>row.status==='sent').map(row=>String(row.vendor_id)).concat(localSent))];const next=receiveReplies(sRef.current,replyMode,externallySent);setS(next);setToast(externallySent.length?`가상 회신을 처리했습니다. 실제 메일 발송 업체 ${externallySent.join(', ')}는 가상 회신에서 제외했습니다.`:'가상 회신 조건을 검증했습니다. 실제 외부 연락은 없습니다.');setDrawer({type:'reply',q:next.inquiries.find(q=>q.vendor==='B')!})}catch(e){setToast((e as Error).message)}finally{setProcessing(null)}}
 async function runOrchestratorCheck(extra:boolean){if(processing)return;setProcessing('orchestrator');await new Promise(resolve=>window.setTimeout(resolve,1050));try{const current=sRef.current;const next=extra?extraAnalyze(current):integrate(current);setS(next);setToast(extra?'추가 분석 결과를 통합 검증했습니다.':'독립 분석 결과를 통합 검증했습니다.')}catch(e){setToast((e as Error).message)}finally{setProcessing(null)}}
 function nextReceipt(id:string){if(!order)return;const next=apply(x=>trackNext(x,order.id,id),'후속 상태와 원료 재고를 갱신했습니다.');if(next){const l=next.orders.find(o=>o.id===order.id)!.lines.find(l=>l.id===id)!;if(l.stage==='QA 승인')setToast('QA 담당자(가상) 승인 기록 완료 · 해당 Lot를 생산 가용재고에 반영했습니다.')}}
 const baseAnalysis=useMemo(()=>analyze(s.data),[s.data]);
 const grid=(kind:TableKind,analysis:Analysis=baseAnalysis,highlight?:Finding)=>{const evidence=highlight?.evidence.filter(e=>e.table===kind);return <DataGrid title={tableLabels[kind]} rows={getRows(s.data,analysis,kind,displayCandidate)} columns={columns[kind]} revision={s.data.revision} highlightRows={evidence?.flatMap(e=>e.ids)} highlightCols={kind==='lots'?['quantity','qc','qa','expiry']:kind==='costs'?['subtotal','total']:['available','date']} onSelect={(row)=>setDrawer({type:'row',kind,row})} onEdit={kind==='costs'?undefined:row=>editRow(kind,row)} onExport={setToast}/>};
 const toolbar=<div className="wf-command-bar"><button onClick={()=>{apply(detect,'재고·생산계획과 기존 PO를 다시 계산했습니다.')}}><RefreshCw size={16}/>새로 고침</button><button onClick={()=>setDrawer({type:'notifications'})}>알림 센터 ({s.notifications.filter(n=>!n.read).length})</button><span/><button onClick={()=>setDrawer({type:'help'})}>시연 안내</button><button onClick={()=>go('settings')}>설정</button></div>;
 const workflow=<ol className="wf-process">{steps.map((name,i)=><li key={name} className={i<stage?'done':i===stage?'active':''}><span>{i<stage?<Check size={13}/>:i+1}</span>{name}</li>)}</ol>;
 const canSendQuote=(q:Inquiry|undefined)=>!!q&&(q.status==='요청중'||(q.status==='미회신'&&q.history.some(h=>h.status==='실제 메일 발송 · 회신 대기')));const mailEligibleVendors=s.data.vendors.filter(v=>canSendQuote(s.inquiries.find(q=>q.vendor===v.id)));
 const inquiryRows:Row[]=s.inquiries.map(q=>{const terms=q.terms||s.data.vendors.find(v=>v.id===q.vendor)!;const expired=Date.parse(s.now)>Date.parse(q.validUntil);const late=Date.parse(s.now)>=Date.parse(q.deadline)&&!replyValid(s,q);return {...q,status:expired&&q.status==='공급 확인'?'회신 만료':late&&q.status==='미회신'?'기한 초과 · 미회신':q.status==='요청중'&&q.history.some(h=>h.status==='실제 메일 발송 · 회신 대기')?'실제 메일 발송 · 회신 대기':q.status,quantity:q.terms?.shipments.reduce((n,l)=>n+l.quantity,0)||0,unitPrice:terms.unitPrice,moq:terms.moq,arrivals:q.terms?.shipments.map(l=>shortDate(l.arrival)+' '+l.quantity+'개').join(' / ')||'미확인',deadline:time(q.deadline),validUntil:time(q.validUntil),tone:late||expired?'danger':q.status==='조건 불확실'?'warning':''};});
 const poRows:Row[]=s.orders.map(o=>({...o,vendorName:o.vendor.name,material:o.product.id,linesCount:o.lines.length,followup:o.lines.filter(l=>l.stage==='QA 승인').length+'/'+o.lines.length+' QA 승인',status:o.status}));
 const caseRows:Row[]=[{id:CASE,material:'MAT-IL7',name:'IL-7 생산 원료 확보',status:s.orders.length?'발주 등록 · 입고 추적':s.deferred?'1차 검토 보류':report&&!stale?report.selected?'2차 승인 대기':'추천 보류':findings.length?'독립 분석 진행':s.inquiries.length?'공급 회신 검토':approved?'공급 확인 요청 대기':'1차 승인 대기',priority:r.level,shortage:r.shortage,target:r.required,needed:r.firstDate,production:r.rows.filter(p=>p.shortage).map(p=>p.id).join(', ')||'예측상 충족',reviewBy:r.reviewBy,owner:'김민서 / 구매팀',revision:'R'+s.data.revision,tone:r.level==='긴급'?'danger':r.level==='위험'?'warning':''}];
 const riskContent=<><div className="wf-risk-title"><Status tone={r.level==='긴급'?'red':'amber'}>{r.level}</Status><h2>IL-7 생산 원료 확보가 필요합니다.</h2></div><dl className="wf-facts"><div><dt>장부 / 생산 가용</dt><dd>{r.ledger} / {r.stock}바이알</dd></div><div><dt>생산 부족 합계</dt><dd>{r.shortage}바이알</dd></div><div><dt>안전재고 포함 확보 목표</dt><dd>{r.required}바이알</dd></div><div><dt>최초 원료 필요일</dt><dd>{r.firstDate}</dd></div><div><dt>검토·승인 추정 기한</dt><dd>{r.reviewBy}</dd></div><div><dt>영향 생산 / 고객 납기</dt><dd>{r.rows.filter(p=>p.shortage).map(p=>`${p.id} · ${p.customer}`).join(' / ')||'현재 부족 없음'}</dd></div></dl><p className="wf-note">목표 수량은 아직 주문 수량이 아닙니다. 공급 회신의 MOQ·분할 조건을 확인한 뒤 실제 발주량을 결정합니다. 고객 납기 역산에는 합성 생산 5일·완제품 확인 1일·포장 1일·운송 1일을 사용합니다.</p></>;
 return <div className="wf-app"><aside className="wf-nav"><a href="#" onClick={e=>{e.preventDefault();go('inbox')}} className="wf-brand">BioFlow <small>ERP / 구매 · 생산</small></a><div className="wf-company">바이오 제조 사업장 <span>1000 · 공정개발</span></div><nav>{nav.map(([id,label])=><button key={id} className={(page===id||(page==='case'&&id==='inbox'))?'active':''} onClick={()=>go(id)}>{label}{id==='inbox'&&<b>1</b>}</button>)}</nav><footer>통합 ERP / v3.0<br/><span>{serverEnabled?"DB 연결 · 실제 AI 별도 실행":"규칙 기반 시연 · API 키 불필요"}</span></footer></aside><div className="wf-shell"><header className="wf-shellbar"><div>자재관리<ChevronRight size={14}/>{page==='case'?'구매요청 상세':nav.find(n=>n[0]===page)?.[1]}</div><div><span className="wf-virtual-clock">시연 시각 {time(s.now)}</span><button aria-label="알림 센터" onClick={()=>setDrawer({type:'notifications'})}><Bell size={20}/><b>{s.notifications.filter(n=>!n.read).length}</b></button><span>김민서</span></div></header>{toolbar}{serverEnabled&&<div className="wf-server-indicator"><b>통합 DB 연결</b><span>변경은 로컬 초안 · 최종 발주 시 서버에서 재검증·저장</span><button onClick={()=>go('connected')}>서버 상태·실제 AI 검토</button></div>}<main className="wf-main">
 {page==='procurement'&&<ProcurementDesk workflow={s} onChange={setS} onConnected={()=>setServerConnected(true)} onAnalyze={next=>{setS(next);setPage('case');setTab('analysis');setRunning(true)}}/>}
 {page==='connected'&&<ServerWorkspace workflow={s} onChange={setS} onConnected={setServerConnected} onAdopt={()=>openCase('recommendation')}/>}
 {page==='inbox'&&<><div className="wf-title"><div><h1>구매요청 업무함</h1><p>생산 부족 자동 감지 · 공급 확인 승인 · 발주 실행</p></div><Button onClick={()=>setModal('risk')}>재고 위험 상세</Button></div><div className="wf-list-summary"><Status tone={r.level==='정상'?'green':'amber'}>{r.level}</Status><span>현재 생산 부족 <b>{r.shortage}개</b></span><span>안전 포함 목표 <b>{r.required}개</b></span><span>검토 대상 <b>1건</b></span><span className="wf-revision">ERP 데이터 R{s.data.revision}</span></div><section className="wf-section"><div className="wf-section-toolbar"><h2>구매요청 목록</h2><button onClick={()=>openCase()}>선택 요청 열기<ArrowRight size={15}/></button></div><DataGrid title="구매요청" rows={caseRows} columns={caseColumns} revision={s.data.revision} onSelect={()=>openCase()} onExport={setToast}/></section><div className="wf-two-columns"><section className="wf-section"><h2>오늘 처리할 업무</h2><div className="wf-task-list"><button onClick={()=>approved?openCase('inquiries'):setModal('first')}><span>01</span><div><b>{approved?'공급업체 회신 확인':'공급업체 확인 1차 승인'}</b><p>{approved?'승인된 경로의 회신·기한·미확인 조건을 검토하세요.':'아직 실제 발주 승인이 아닙니다. 승인 전에는 문의를 시작하지 않습니다.'}</p></div><ChevronRight size={18}/></button><button onClick={()=>openCase('analysis')}><span>02</span><div><b>독립 분석 및 통합 검증</b><p>동일한 데이터·회신 버전으로 4개 AI가 분석하고 Orchestrator가 통합합니다.</p></div><ChevronRight size={18}/></button><button onClick={()=>go('tracking')}><span>03</span><div><b>등록 발주 · 입고 품질 추적</b><p>{s.orders.length?`${s.orders[0].id} · ${s.orders[0].lines.length}개 납품 회차`:'발주 등록 후 출하·입고·QC·QA 기록을 확인합니다.'}</p></div><ChevronRight size={18}/></button></div></section><section className="wf-section"><h2>최근 알림</h2><div className="wf-notice-list">{s.notifications.slice(0,4).map(n=><button key={n.id} onClick={()=>{setDrawer({type:'notifications'});setS({...s,notifications:s.notifications.map(x=>x.id===n.id?{...x,read:true}:x)})}}><b>{n.title}</b><p>{n.body}</p><small>{time(n.at)}</small></button>)}</div></section></div></>}
 {page==='case'&&<><button className="wf-back" onClick={()=>go('inbox')}><ArrowLeft size={15}/>구매요청 목록</button><div className="wf-object-header"><div><small>{CASE} / MAT-IL7 / {s.data.products[0].sku}</small><h1>IL-7 생산 원료 확보</h1><p>담당 구매팀 김민서 · 생산 {s.data.productions.length}건 · 데이터 R{s.data.revision}</p></div><Status tone={s.orders.length?'green':stale?'red':'blue'}>{s.orders.length?'ERP 발주 등록':stale?'조건 변경 · 재분석 필요':caseRows[0].status as string}</Status></div>{workflow}<div className="wf-object-tabs">{([['overview','요청 개요'],['inquiries','공급업체 요청·회신'],['analysis','독립 분석·통합'],['recommendation','최종 추천·승인']] as const).map(([id,label])=><button key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}>{label}</button>)}</div>
 {tab==='overview'&&<><section className="wf-section"><div className="wf-section-toolbar"><h2>확보 요청과 승인 범위</h2><Button onClick={()=>setModal('first')} variant={approved?'outline':'default'}>{approved?'1차 승인 기록 확인':'공급업체 확인 승인'}</Button></div><div className="wf-overview-facts">{riskContent}</div></section><section className="wf-section"><h2>영향받는 생산 · 고객 납기</h2><DataGrid title="필요일·고객 납기" rows={downstreamRows(s.data).map(p=>({...p,needed:p.il7,status:p.customerRisk?'생산계획·납기 재조정 필요':'합성 공정기간 기준 예상 충족',tone:p.customerRisk?'danger':''}))} columns={downstreamColumns} revision={s.data.revision} onSelect={row=>setDrawer({type:'row',kind:'production',row})} onEdit={row=>editRow('production',row)} onExport={setToast}/><p className="wf-note">판단 기준은 고객 납기입니다. 원료 투입일은 생산·완제품 확인·포장·고객 운송을 반영해 역산하며, 합성 계획을 실제 납기 보장으로 표시하지 않습니다.</p></section></>}
 {tab==='inquiries'&&<><div className="wf-context-actions"><Button disabled={!approved||!!s.inquiries.length} onClick={()=>apply(startInquiries,'가상 문의를 생성했습니다. 업체로 실제 전송하지 않았습니다.')}>공급 확인 요청 생성</Button><Button variant="outline" disabled={!approved||!mailEligibleVendors.length} onClick={openQuoteComposer}><Mail size={16}/> 실제 견적 메일 작성</Button><select aria-label="가상 회신 유형" value={replyMode} onChange={e=>setReplyMode(e.target.value as ReplyMode)}><option value="normal">정상 회신 · A/B 확약</option><option value="missing">B 미회신</option><option value="unavailable">전체 공급 불가</option><option value="partial">B 8개 부분 공급</option></select><Button variant="outline" disabled={processing==='replies'||!s.inquiries.some(q=>q.status==='요청중')} onClick={receive}>{processing==='replies'?<><RefreshCw className="wf-spin" size={15}/> 회신 검증 중</>:'가상 회신 수신'}</Button><button disabled={!s.inquiries.length||!!processing} onClick={()=>apply(expireReplies,'시연 시간을 4일 전개했습니다. 회신과 견적 유효성을 확인하세요.')}>기한 경과 시뮬레이션</button><span/><Button disabled={analysisIssues.length>0||!!processing} title={analysisIssues[0]} onClick={beginAnalysis}>독립 분석 시작</Button></div>{processing==='replies'&&<div className="wf-work-banner" role="status" aria-live="polite"><RefreshCw className="wf-spin" size={21}/><div><b>가상 회신 데이터 생성 · 공급 조건 검증 중</b><p>A/B/C 응답 상태와 MOQ, 확약 수량, 분할 납기를 확인한 뒤 표에 반영합니다. 외부 연락은 없습니다.</p><div className="wf-indeterminate" aria-label="가상 회신 조건 검증 중"><i/></div></div></div>}{approved&&s.inquiries.length>0&&analysisIssues.length>0&&!processing&&<div className="wf-analysis-notice" role="status"><b>분석 선행조건 · 업체 회신 확인</b><p>{analysisIssues[0]}</p></div>}{!approved&&<div className="wf-message warning">1차 승인이 필요합니다. 승인 전에는 업체 문의를 진행할 수 없습니다.<button onClick={()=>setModal('first')}>승인 검토</button></div>}<section className="wf-section"><div className="wf-section-toolbar"><h2>공급업체 확인 요청·회신</h2><span>가상 회신은 시뮬레이션 · 실제 메일은 별도 승인 발송 · 회신 원문과 확약을 별도 보존</span></div><DataGrid title="업체 요청·회신" rows={inquiryRows} columns={inquiryColumns} revision={s.data.revision} onSelect={row=>setDrawer({type:'reply',q:s.inquiries.find(q=>q.id===row.id)!})} onExport={setToast} empty="1차 승인 후 공급 확인 요청을 생성하세요."/></section><div className="wf-next-action"><b>다음 조치</b><p>미회신은 기한 전 재문의, 조건 불확실은 누락 항목 재질의, 공급 불가는 대체 경로 검토로 구분합니다. 최종 대응 기한 이후에는 재문의 대신 일정·긴급 조달을 검토합니다.</p></div></>}
 {tab==='analysis'&&<><div className="wf-context-actions"><Button onClick={beginAnalysis} disabled={running||!!processing||analysisIssues.length>0}>Orchestrator 작업 배분</Button><Button variant="outline" onClick={()=>{setAnalysisError('');setRunning(!running)}} disabled={analysisIssues.length>0||(!running&&!findings.length)||!!processing||!!report&&!stale}>{running?'실행 일시정지':'실행 계속'}</Button><button onClick={analyzeAll} disabled={analysisIssues.length>0||running||!!processing}>남은 분석 모두 실행</button><select aria-label="작업 재생 속도" value={speed} onChange={e=>setSpeed(Number(e.target.value))}><option value={650}>빠르게</option><option value={1300}>기본</option><option value={2600}>발표용</option></select><span/><Status tone={running?'blue':'normal'}>{findings.length}/4 독립 결과</Status></div>{analysisIssues.length>0&&<div className="wf-analysis-notice" role="status"><b>분석 시작 전 · 공급 확인 단계</b><p>{analysisIssues[0]}</p><p>가상 업체 회신은 해당 탭의 ‘가상 회신 수신’으로 처리합니다. 실제 메일을 보낸 업체는 자동 회신 대상에서 제외됩니다.</p><Button variant="outline" onClick={()=>openCase('inquiries')}>공급업체 요청·회신 확인</Button></div>}{analysisError&&analysisIssues.length===0&&<div className="wf-analysis-notice error" role="alert"><b>분석 중단</b><p>{analysisError}</p></div>}{!analysisIssues.length&&!findings.length&&!running&&!analysisError&&<div className="wf-analysis-notice" role="status"><b>분석 준비 완료</b><p>회신 상태를 확인했습니다. 상단 ‘Orchestrator 작업 배분’을 누르면 네 AI가 ERP 데이터 분석을 시작합니다.</p></div>}{running&&<div className="wf-work-banner wf-analysis-banner" role="status" aria-live="polite"><RefreshCw className="wf-spin" size={22}/><div className="wf-work-copy"><b>{activeAgent?`${activeAgent.name} · ERP 데이터 독립 검토 중`:'Orchestrator · 4개 분석 결과 통합 검증 중'}</b><p>{activeAgent?`${activeAgent.task} · 완료된 분석 ${findings.length}/4건`:"필수조건과 부서별 결과를 대조합니다."}</p><div className="wf-step-progress" role="progressbar" aria-label="완료된 실제 분석 단계" aria-valuenow={analysisProgress} aria-valuemin={0} aria-valuemax={5}><i style={{width:`${analysisProgress/5*100}%`}}/></div><small>{analysisProgress}/5 실제 분석 단계 완료 · 다음 단계는 결과 저장 후 시작</small></div></div>}{processing==='orchestrator'&&<div className="wf-work-banner wf-orchestrator-banner" role="status" aria-live="polite"><RefreshCw className="wf-spin" size={22}/><div><b>Orchestrator · 추가 근거 재검토 및 전략 통합 중</b><p>요청된 Agent의 계산 결과를 회수하고 발주 조건을 다시 검증합니다.</p><div className="wf-indeterminate" aria-label="Orchestrator 통합 검증 중"><i/></div></div></div>}<section className="wf-section wf-agent-section"><div className="wf-section-toolbar"><h2>독립 분석 작업</h2><span>공유 ERP·회신 스냅샷 R{s.data.revision} / 부서 간 직접 토론 없음</span></div><div className="wf-orchestrator-dispatch"><b>Orchestrator</b><span>작업 배분 → 4개 독립 산출물 회수 → 필요 시 해당 AI에 추가 요청 → 통합 검증</span></div><DataGrid title="AI 독립 분석" rows={agents.map(agent=>{const f=findings.find(f=>f.agent===agent.id);return {id:agent.id,name:agent.name,task:agent.task,status:f?'완료':analysisIssues.length?'선행 업무 대기':activeAgent?.id===agent.id?'분석 중':'대기',result:f?.result||(analysisIssues.length?analysisIssues[0]:activeAgent?.id===agent.id?agent.task+' · ERP 데이터를 조회·계산 중입니다.':running?'앞선 작업 결과를 확인한 뒤 분석을 실행합니다.':findings.length?'실행 계속을 눌러 남은 분석을 진행하세요.':'Orchestrator 작업 배분을 눌러 분석을 시작하세요.'),version:f?'R'+f.revision:'—',constraints:f?.constraints.join(' / ')||'—',evidenceCount:f?.evidence.length||0};})} columns={agentColumns} revision={s.data.revision} onSelect={row=>{const f=findings.find(f=>f.agent===row.id);if(f)setDrawer({type:'finding',finding:f});else setToast('해당 분석이 실행된 뒤 근거를 조회할 수 있습니다.')}} onExport={setToast}/></section>
 {s.extraRequests.length>0&&<section className="wf-section"><div className="wf-section-toolbar"><h2>Orchestrator 추가 분석 요청</h2><Button variant="outline" disabled={processing==='orchestrator'||s.extraRequests.every(x=>x.resolved)} onClick={()=>runOrchestratorCheck(true)}>{processing==='orchestrator'?<><RefreshCw className="wf-spin" size={15}/> 검증 중</>:'추가 검증 실행'}</Button></div><table className="wf-plain-table"><thead><tr><th>요청 AI</th><th>충돌 및 요청 사유</th><th>상태</th></tr></thead><tbody>{s.extraRequests.map(q=><tr key={q.id}><td>{agents.find(a=>a.id===q.agent)?.name}</td><td>{q.reason}</td><td><Status tone={q.resolved?'green':'amber'}>{q.resolved?'검증 회수':'추가 확인 필요'}</Status></td></tr>)}</tbody></table><p className="wf-note">재검토는 1회로 제한합니다. 해결되지 않은 제약은 담당자에게 전달하고 임의 승인하지 않습니다.</p></section>}
 <section className="wf-section"><div className="wf-section-toolbar"><h2>통합 검증 결과</h2><Button variant="outline" disabled={findings.length!==4||!!processing||running} onClick={()=>runOrchestratorCheck(false)}>{processing==='orchestrator'?<><RefreshCw className="wf-spin" size={15}/> 통합 중</>:'Orchestrator 통합 검증'}</Button></div>{report&&!stale?<div className="wf-result-object"><Status tone={report.selected?'green':'red'}>{report.selected?'추천안 확정':'추천 보류'}</Status><h2>{report.summary}</h2><ul>{report.actions.map(x=><li key={x}>{x}</li>)}</ul><button onClick={()=>setTab('recommendation')}>비교표와 2차 승인 검토<ArrowRight size={16}/></button></div>:<div className="wf-empty">4개 독립 분석을 수집한 후 동일 버전의 결과를 통합합니다.</div>}</section><section className="wf-section"><div className="wf-section-toolbar"><h2>실행 중 참조 데이터 · 행/셀 강조</h2><span>{findings.at(-1)?.id||'작업 실행 대기'}</span></div><div className="wf-subtabs">{(['lots','production','inquiries','shipments','costs'] as const).map(k=><button key={k} className={analysisTable===k?'active':''} onClick={()=>setAnalysisTable(k)}>{k==='inquiries'?'업체 회신':tableLabels[k]}</button>)}</div>{analysisTable==='inquiries'?<DataGrid title="분석 참조 회신" rows={inquiryRows} columns={inquiryColumns} revision={s.data.revision} highlightRows={findings.find(f=>f.agent==='purchase')?.evidence.flatMap(e=>e.ids)} highlightCols={['status','unitPrice','quantity','arrivals']} onSelect={row=>setDrawer({type:'reply',q:s.inquiries.find(q=>q.id===row.id)!})} onExport={setToast}/>:grid(analysisTable,a,drawer?.type==='finding'?drawer.finding:findings.at(-1))}{findings.at(-1)&&<div className="wf-live-formula"><b>{agents.find(a=>a.id===findings.at(-1)!.agent)?.name} · 실제 계산</b><code>{findings.at(-1)!.evidence[0]?.formula}</code><p>{findings.at(-1)!.evidence[0]?.result}</p></div>}</section><section className="wf-section"><h2>실행 로그</h2><DataGrid title="분석 작업 로그" rows={s.audit.filter(e=>e.actor.includes('AI')||e.actor.includes('Orchestrator')||e.actor==='재고 계산기').map(e=>({...e,time:time(e.at)}))} columns={auditColumns} revision={s.data.revision} onSelect={row=>{const f=[...s.findings,...s.reports.flatMap(r=>r.findings)].find(f=>f.id===row.entity);if(f){setDrawer({type:'finding',finding:f});setAnalysisTable((f.evidence[0]?.table||'lots') as TableKind|'inquiries')}else setDrawer({type:'row',kind:'audit',row})}} onExport={setToast}/></section></>}
 {tab==='recommendation'&&<>{stale&&<div className="wf-message warning"><b>이전 추천 만료</b> 원본 데이터/견적/회신이 변경됐습니다. 같은 승인으로 발주서를 생성할 수 없습니다.<button onClick={beginAnalysis}>재분석</button></div>}{!report?<div className="wf-empty">독립 분석과 Orchestrator 통합 후 추천서를 확인할 수 있습니다.<Button onClick={beginAnalysis}>분석 시작</Button></div>:<><section className="wf-section"><div className="wf-section-toolbar"><h2>최종 발주 전략 비교</h2><Status tone={report.selected&&!stale?'green':'amber'}>{report.selected&&!stale?'담당자 최종 승인 필요':'추천 보류/재검증'}</Status></div><DataGrid title="통합 발주 전략" rows={report.strategies.map(t=>({...t,name:t.name,unitPrice:report.snapshot.vendors.find(v=>v.id===t.vendor)!.unitPrice,arrivals:t.option.deliveries.map(l=>`${l.arrival} ${l.quantity}개`).join(' / '),status:t.eligible?'필수조건 충족':t.reasons.join(' · '),tone:t.eligible?'':'warning'}))} columns={strategyColumns} revision={report.revision} onSelect={row=>setDrawer({type:'row',kind:'strategy',row})} onExport={setToast}/><div className="wf-report-footer"><b>{report.id} / R{report.revision}</b><span>분석·원본·회신 스냅샷 보존</span></div></section><div className="wf-two-columns"><section className="wf-section"><h2>추천 사유 · 조정 결과</h2><div className="wf-prose"><h3>{report.summary}</h3><p>최초 확보 목표 {report.analysis.need.required}개와 실제 주문량은 MOQ·주문배수 검증으로 결정했습니다. 안전재고와 생산 부족량은 별도 계산했습니다.</p><p>적기 납품은 고객 납기 기준입니다. 생산 5일 → 완제품 확인 1일 → 포장 1일 → 고객 운송 1일의 합성 기간으로 역산하고, 기존 생산계획이 맞지 않으면 변경 승인을 요청합니다.</p>{report.actions.map(x=><p className="wf-warning-text" key={x}>{x}</p>)}<p>일부 확약량은 ‘부분 공급’으로 구분하여 비교합니다. 단독으로 부족한 부분 공급이나 미확약 물량을 전체 수요 충족으로 표시하지 않습니다. 다른 공급 경로와 조합하려면 회차별 추가 확약이 필요합니다.</p></div></section><section className="wf-section"><h2>2차 승인 · 발주 등록</h2><div className="wf-prose"><dl className="wf-compact-dl"><div><dt>최종 공급안</dt><dd>{report.selected?report.strategies.find(x=>x.vendor===report.selected)?.name:'추천 가능한 확정안 없음'}</dd></div><div><dt>구매예산</dt><dd>{won(report.snapshot.config.budget)}</dd></div><div><dt>현재 데이터</dt><dd>R{s.data.revision} / {stale?'변경 감지':'일치'}</dd></div><div><dt>회신·견적 유효성</dt><dd>{report.selected&&replyValid(s,s.inquiries.find(q=>q.vendor===report.selected)!)?'유효':'미확인/만료/해당 없음'}</dd></div></dl><Button onClick={()=>setModal('final')} disabled={finalErrors(s).length>0}>최종 발주 승인 검토</Button>{finalErrors(s).map(x=><p className="wf-warning-text" key={x}>{x}</p>)}<p className="wf-note">이 승인은 실제 주문 전송이나 업체 수락, 품질 사용 승인이 아닙니다. 승인 조건으로 내부 가상 PO를 생성합니다. 예산 초과안은 별도 예산 승인 없이는 자동 채택하지 않습니다.</p>{s.orders.length>0&&<button className="wf-link" onClick={()=>{setDrawer({type:'po',po:s.orders[0]})}}>등록 발주서 상세 · 인쇄</button>}</div></section></div>{(report.combinations||[]).length>0&&<section className="wf-section"><h2>부분 공급 + 보충 조합 검증</h2><table className="wf-plain-table"><thead><tr><th>조합 · 실제 MOQ</th><th>구매·운송</th><th>총비용</th><th>생산 부족 / 폐기</th><th>통합 판정</th></tr></thead><tbody>{report.combinations!.map(c=><tr key={c.id}><td>{c.name} / 총 {c.quantity}개</td><td>{won(c.subtotal)}</td><td>{won(c.total)}</td><td>{c.shortage} / {c.waste}개</td><td>{c.reasons.join(' · ')}</td></tr>)}</tbody></table><p className="wf-note">두 업체의 확약 일정·MOQ를 결합해 재고 할당과 지급일 현금을 다시 계산합니다. 기존 소계의 단순 합계에 보관비를 중복 가산하지 않습니다.</p></section>}<section className="wf-section"><h2>잔여 위험과 추가 확인</h2><div className="wf-prose"><ul>{report.analysis.warnings.map(w=><li key={w}>{w}</li>)}<li>부분 공급의 조합, 긴급 운송, 지급 조건 변경 등 미확약 조치를 이미 확보된 물량으로 계산하지 않습니다.</li></ul></div></section></>}
 </>}
 </>}
 {(page==='inventory'||page==='production'||page==='suppliers')&&<><div className="wf-title"><div><h1>{page==='inventory'?'원료 · Lot 재고':page==='production'?'생산 · 고객 납기 계획':'공급업체 · 견적 관리'}</h1><p>행을 선택하면 우측에서 상세를 확인합니다. 편집 시 연결 계산과 승인 조건을 재검증합니다.</p></div><button className="wf-link" onClick={()=>openCase()}>구매요청 상세</button></div><div className="wf-context-actions">{page==='inventory'?<><span>IL-7 장부 <b>{r.ledger}</b>개</span><span>생산 가용 <b>{r.stock}</b>개</span><button onClick={()=>setModal('risk')}>부족·예약·기존 발주 영향</button></>:page==='production'?<><span>역산 규칙 {downstream.rule}</span><button onClick={()=>setDrawer({type:'help'})}>공정 기간·납기 규칙</button></>:<><button onClick={()=>openCase('inquiries')}>업체 요청·회신 업무</button><span>가격·MOQ 변경은 기존 공급 회신을 재확인합니다.</span></>}<span/><button onClick={()=>editRow('config',{id:'CONFIG'})}>QC/QA·예산 규칙</button></div><section className="wf-section">{page==='inventory'?grid('lots'):page==='production'?<DataGrid title="고객 납기 역산" rows={downstreamRows(s.data).map(p=>({...p,status:p.customerRisk?'고객 납기 영향 있음':'계획상 충족',tone:p.customerRisk?'danger':''}))} columns={downstreamColumns} revision={s.data.revision} onSelect={row=>setDrawer({type:'row',kind:'production',row})} onEdit={row=>editRow('production',row)} onExport={setToast}/>:grid('quotes')}</section>{page==='production'&&<section className="wf-section"><div className="wf-section-toolbar"><h2>공급안별 입고 · QC/QA 예상일</h2><select aria-label="공급안 선택" value={displayCandidate} onChange={e=>setDisplayCandidate(e.target.value)}>{s.data.vendors.map(v=><option key={v.id} value={v.id}>{v.name}</option>)}</select></div>{grid('shipments')}</section>}{page==='inventory'&&<p className="wf-note">발주 등록은 현재 재고를 늘리지 않습니다. 입고 시 장부에 기록하고, QC 적합 및 QA 담당자의 승인 이후 생산 가용량에 포함합니다. 다른 생산에 배정한 수량은 한 번만 차감합니다.</p>}</>}
 {page==='orders'&&<><div className="wf-title"><div><h1>발주서 · ERP 등록</h1><p>승인된 전략 버전, 조건, 납품 회차와 발주 문서를 보존합니다.</p></div><Button onClick={()=>openCase('recommendation')} variant="outline">승인 대기 검토</Button></div><section className="wf-section"><DataGrid title="ERP 발주 내역" rows={poRows} columns={poColumns} revision={s.data.revision} onSelect={row=>{setSelectedPO(row.id);setDrawer({type:'po',po:s.orders.find(o=>o.id===row.id)!})}} onExport={setToast} empty="등록된 PO가 없습니다. 2차 승인 후 발주서를 생성합니다."/></section><div className="wf-message info">내부 PO 등록과 업체의 주문 수락은 다릅니다. 실제 공급업체 전송은 하지 않습니다.</div></>}
 {page==='tracking'&&<><div className="wf-title"><div><h1>출하 · 입고 · 품질 추적</h1><p>발주 회차별 진행 상태와 실제 Lot의 품질 사용 승인 여부를 분리합니다.</p></div>{order&&<button className="wf-link" onClick={()=>setDrawer({type:'po',po:order})}>발주서 상세 · 인쇄</button>}</div>{!order?<div className="wf-empty">2차 승인과 발주 등록 후 회차 추적을 시작할 수 있습니다.<Button onClick={()=>openCase('recommendation')}>발주 검토로 이동</Button></div>:<><div className="wf-context-actions"><select aria-label="추적할 발주" value={order.id} onChange={e=>setSelectedPO(e.target.value)}>{s.orders.map(o=><option key={o.id}>{o.id}</option>)}</select><span>{order.vendor.name} · {order.quantity}바이알</span><button onClick={()=>{apply(trackReview,'현재 PO·Lot·생산계획으로 후속 영향을 재계산했습니다.');setDrawer({type:'notifications'})}}>AI 후속 재분석</button><button onClick={()=>apply(finishProduction,'생산 투입 시점까지 전개하고 승인 재고만 배정했습니다.')}>생산 투입 반영</button></div><section className="wf-section"><DataGrid title="PO 회차 추적" rows={order.lines.map(l=>({...l,status:l.blocked?'품질 보류':l.stage,po:order.id,quantity:l.quantity,actualArrival:l.actualArrival||'미입고',qaState:l.stage==='QA 승인'?'사용 승인(가상)':'사용 미승인',issue:l.issue||'—',tone:l.blocked?'danger':l.qcDelay?'warning':''}))} columns={trackingColumns} revision={s.data.revision} onSelect={row=>{setSelectedLine(row.id);setDrawer({type:'row',kind:'receipt',row})}} onExport={setToast}/></section><section className="wf-section"><div className="wf-section-toolbar"><h2>회차 처리 · 가상 담당자 기록</h2><select aria-label="처리할 납품 회차" value={poLine?.id||''} onChange={e=>setSelectedLine(e.target.value)}>{order.lines.map(l=><option key={l.id} value={l.id}>{l.id} · {l.quantity}개</option>)}</select></div>{poLine&&<div className="wf-receipt-object"><div className="wf-receipt-summary"><h3>{poLine.id} / {poLine.lot}</h3><Status tone={poLine.blocked?'red':poLine.stage==='QA 승인'?'green':'blue'}>{poLine.blocked?'QA 보류':poLine.stage}</Status><p>입고 예정 {poLine.arrival} · QC {poLine.qcEnd} · QA/사용 가능 예상 {poLine.available}</p></div><ol className="wf-receipt-steps">{(['발주 등록','출하','입고','QC 검사','QC 적합','QA 승인'] as const).map(name=><li key={name} className={['발주 등록','출하','입고','QC 검사','QC 적합','QA 승인'].indexOf(name)<=['발주 등록','출하','입고','QC 검사','QC 적합','QA 승인'].indexOf(poLine.stage)?'done':''}>{name}</li>)}</ol><div className="wf-context-actions"><Button disabled={poLine.stage==='QA 승인'||poLine.blocked} onClick={()=>nextReceipt(poLine.id)}>{poLine.stage==='발주 등록'?'출하 기록':poLine.stage==='출하'?'입고 기록':poLine.stage==='입고'?'QC 검사 시작':poLine.stage==='QC 검사'?'QC 적합 기록':poLine.stage==='QC 적합'?'QA 승인 기록 (가상 담당자)':'QA 승인 완료'}</Button><button disabled={poLine.stage==='QA 승인'} onClick={()=>{setSelectedLine(poLine.id);const n=apply(x=>trackingIssue(x,order.id,poLine.id,'delay'));if(n)setModal('delay')}}>QC 시작 3일 지연</button><button disabled={poLine.stage==='QA 승인'||poLine.blocked} onClick={()=>{if(apply(x=>trackingIssue(x,order.id,poLine.id,'quality')))setModal('delay')}}>온도 이탈 · QA 보류</button></div><p className="wf-note">QC/QA 상태는 AI가 변경하지 않습니다. 위 버튼은 담당자의 합성 검사·승인 근거를 기록하는 시연 기능입니다. 회차 처리 시 업무 시각이 전개되며, 해당 투입일 이전에 QA 승인된 재고만 생산에 한 번씩 배정합니다. 지연 승인분을 과거 생산에 소급 투입하지 않습니다.</p></div>}</section><section className="wf-section"><h2>현재 생산 영향 · 기존 발주 포함</h2><DataGrid title="발주 후 생산 영향" rows={r.rows.map(p=>({...p,status:p.shortage?'원료 부족':p.after<s.data.products[0].safety?'안전재고 미달':'예측 충족',tone:p.shortage?'danger':'',customer:p.customer}))} columns={impactColumns} revision={s.data.revision} onSelect={row=>setDrawer({type:'row',kind:'production-impact',row})} onExport={setToast} empty="모든 계획 투입이 반영되었습니다."/><p className="wf-note">생산 반영 {s.produced.length}/{s.data.productions.length}건 · 현재 승인 가용재고 {r.stock}바이알 · 미반영 생산만 수요에 남겨 중복 배정을 방지합니다.</p></section></>}
 </>}
 {page==='audit'&&<><div className="wf-title"><div><h1>승인 · 분석 · 업무 이력</h1><p>최초 알림, 두 단계 승인, 회신, 분석 스냅샷, PO와 후속 기록을 연결합니다.</p></div></div><section className="wf-section"><h2>두 단계 승인 기록</h2><DataGrid title="승인 기록" rows={s.approvals.map(x=>({...x,time:time(x.at),kindLabel:x.kind===1?'1차 공급 확인':'2차 구매 발주',status:x.decision}))} columns={[{key:'id',label:'승인번호'},{key:'kindLabel',label:'승인 구분'},{key:'status',label:'결정'},{key:'actor',label:'담당자'},{key:'reason',label:'승인 범위'},{key:'time',label:'시각'}]} revision={s.data.revision} onSelect={row=>setDrawer({type:'row',kind:'approval',row})} onExport={setToast}/></section><section className="wf-section"><h2>업무 감사 기록</h2><DataGrid title="업무 감사 이력" rows={s.audit.map(x=>({...x,time:time(x.at)}))} columns={auditColumns} revision={s.data.revision} onSelect={row=>setDrawer({type:'row',kind:'audit',row})} onExport={setToast}/></section><section className="wf-section"><h2>통합 전략 버전</h2><DataGrid title="통합 전략 이력" rows={s.reports.map(x=>({...x,status:x.selected?'추천안 있음':'보류',time:time(x.at),id:x.id,summary:x.summary}))} columns={[{key:'id',label:'전략 검증번호'},{key:'revision',label:'원본 버전'},{key:'status',label:'판정'},{key:'summary',label:'당시 결정'},{key:'time',label:'생성 시각'}]} revision={s.data.revision} onSelect={row=>setDrawer({type:'row',kind:'report',row})} onExport={setToast}/></section></>}
 {page==='settings'&&<><div className="wf-title"><div><h1>기준정보 · 시연 설정</h1><p>기존 IL-7 합성 데이터와 v2.1 프로세스 기준을 구분합니다.</p></div></div><section className="wf-section"><h2>실행 모드 및 데이터 기준</h2><div className="wf-prose"><p><b>업무 시뮬레이션:</b> 실제 ERP 조회·산술·승인 검증 함수를 실행하고, 공급 회신과 검사 기록은 합성 데이터로 생성합니다. 외부 LLM/API와 실제 메일 발송은 각각 별도 설정·승인이 필요합니다. 공급 회신·검사 기록·주문은 시뮬레이션입니다.</p><p>규칙 {downstream.rule}: 생산 5일, 완제품 확인 1일, 포장 1일, 고객 운송 1일. 날짜는 달력일, 미개봉 동일 규격 바이알 단위입니다. 기존 승인 재고2 / 생산12 / 안전2 / 신규12, A 소계1,610만원 / B 1,230만원을 유지합니다.</p><p><a href="./references/bioflow-plan-v2.1.pdf" target="_blank" rel="noreferrer">v2.1 통합 기획안 PDF</a> · <a href="./references/scenario_1.pdf" target="_blank" rel="noreferrer">기존 IL-7 기준 PDF</a></p><p>보류 Lot의 CoA 원인·해제 조건, 비용 단가, 제품 규격 기호 U1/U2, 후속 공정 기간과 문서 ID는 추가 합성 설정입니다. 실제 제품 함량·공식 보관 규격은 실물 도입 전 확인해야 합니다.</p><div className="wf-context-actions"><Button variant="outline" onClick={()=>editRow('config',{id:'CONFIG'})}>예산 · QC/QA 규칙 편집</Button><button onClick={()=>setDrawer({type:'help'})}>3–5분 시연 순서</button><button onClick={onPrevious}>이전 분석 화면 열기</button></div></div></section><section className="wf-section"><h2>메일 연결</h2><div className="wf-prose"><p>서버에 등록된 발신·수신 기본 주소를 확인하고 Gmail 앱 비밀번호로 메일 발송을 활성화합니다.</p><Button variant="outline" onClick={openMailSettings}><Mail size={16}/> 메일 연결 설정</Button></div></section><section className="wf-section"><h2>독립 시나리오 · 원본 변경</h2><div className="wf-context-actions">{([['base','기준 데이터 복원'],['qc-delay','발주 전 QC +3일'],['cash','지급일 현금 부족'],['c-quality','C 제품 미승인']] as [Scenario,string][]).map(([id,label])=><button key={id} onClick={()=>{const n=apply(x=>variant(x,id));if(n)setModal('change')}}>{label}</button>)}</div><p className="wf-note">발주 등록 후에는 위 독립 데이터 전환 대신 실제 PO 회차의 지연·보류 버튼으로 영향을 검토합니다.</p></section><section className="wf-section"><h2>전체 시연 초기화</h2><div className="wf-prose"><p>현재 v2.1 승인·회신·분석·PO·후속 이력을 초기화합니다. 이전 버전의 별도 저장 데이터는 보존합니다.</p><Button variant="danger" onClick={()=>setModal('reset')}>전체 업무 시연 초기화</Button></div></section></>}
 <footer className="wf-main-footer">합성 ERP 업무 데이터 · 공급회신/주문 시뮬레이션 · SMTP 메일 별도 발송 · 구매승인과 품질 사용승인 분리<span>BioFlow v2.1 / R{s.data.revision}</span></footer></main></div>
 <DecisionModal title={modal==='mail-settings'?'메일 연결 설정':'실제 견적 요청 메일'} open={modal==='mail'||modal==='mail-settings'} onClose={()=>{setModal(null);setMailError('');setMailPassword('')}}>
   <div className="wf-mail-notice"><Mail size={19}/><div><b>{modal==='mail-settings'?'Gmail 계정 연결':'실제 외부 메일 발송'}</b><p>{modal==='mail-settings'?'계정과 기본 수신 주소를 확인하고 Gmail 인증을 연결합니다. 연결 확인 중에는 메일을 보내지 않습니다.':'승인자 세션과 서버 SMTP 설정이 필요합니다. 발송 전 수신 주소, 일정, 첨부 CSV를 직접 확인하세요. 메일 회신은 자동 수신되지 않습니다.'}</p></div></div>
   {!mailSettings&&<div className="wf-message warning"><b>승인자 인증 필요</b><Button variant="outline" disabled={mailConnecting} onClick={connectMailApprover}>{mailConnecting?'연결 중…':'로컬 승인자 계정 연결'}</Button></div>}
   {mailSettings&&<div className={'wf-message '+(mailSettings.configured?'info':'warning')}><b>{mailSettings.configured?'메일 발송 설정 준비':'Gmail 인증 필요'}</b><span>{mailSettings.default_sender} → {mailSettings.default_recipient||'수신 주소 입력'}</span></div>}
   {mailSettings&&!mailSettings.configured&&mailSettings.connection_setup_available&&<form className="wf-mail-connect" onSubmit={connectGmail}><label>Gmail 앱 비밀번호<input type="password" required autoComplete="new-password" value={mailPassword} maxLength={32} placeholder="16자리 앱 비밀번호" onChange={e=>setMailPassword(e.target.value)}/></label><p>일반 Google 로그인 비밀번호 대신 <a href="https://myaccount.google.com/apppasswords" target="_blank" rel="noreferrer">앱 비밀번호</a>를 입력하세요. 인증 후 서버에만 저장되며 브라우저에 보관하지 않습니다.</p><Button type="submit" disabled={mailConnecting||!mailPassword.trim()}>{mailConnecting?<><RefreshCw className="wf-spin" size={16}/> Gmail 인증 확인 중</>:'Gmail 연결 · 메일 활성화'}</Button></form>}
   {mailSettings&&!mailSettings.configured&&!mailSettings.connection_setup_available&&<div className="wf-message warning">서버의 SMTP 호스트와 계정 설정을 먼저 확인하세요.</div>}
   {mailError&&<div className="wf-message warning" role="alert">{mailError}</div>}
   {mailSentId&&<div className="wf-mail-success" role="status"><Check size={20}/><div><b>메일 서버가 발송을 수락했습니다.</b><p>발송 ID {mailSentId} · 메일함의 실제 전달/회신 상태는 별도 확인이 필요합니다.</p><Button onClick={()=>setModal(null)}>닫기</Button></div></div>}
   {modal==='mail'&&!mailSentId&&<form onSubmit={sendQuoteEmail}>
    <div className="wf-mail-form">
     <label>공급업체<select required value={mailForm?.vendor_id||''} onChange={e=>{const v=s.data.vendors.find(x=>x.id===e.target.value);if(v&&mailForm)setMailForm({...mailForm,vendor_id:v.id,vendor_name:v.name})}}>{mailEligibleVendors.map(v=><option key={v.id} value={v.id}>{v.id} · {v.name}</option>)}</select></label>
     <label>공급업체 표시명<input required maxLength={200} value={mailForm?.vendor_name||''} onChange={e=>mailForm&&setMailForm({...mailForm,vendor_name:e.target.value})}/></label>
     <label>보내는 사람 이메일<input type="email" required maxLength={254} autoComplete="email" value={mailForm?.sender_email||''} onChange={e=>mailForm&&setMailForm({...mailForm,sender_email:e.target.value})}/><small>허용 발신 주소: {mailSettings?.allowed_senders.join(', ')||'서버 SMTP 설정 확인 중'}{mailForm?.sender_email&&mailSettings&&!mailSettings.allowed_senders.includes(mailForm.sender_email.trim().toLowerCase())&&<em className="wf-mail-sender-error">등록된 발신 주소를 사용하세요.</em>}</small></label>
     <label>받는 사람 이메일<input type="email" required maxLength={254} autoComplete="off" placeholder="구매 담당자 이메일" value={mailForm?.recipient_email||''} onChange={e=>mailForm&&setMailForm({...mailForm,recipient_email:e.target.value})}/></label>
     <label className="full">제목<input required maxLength={250} value={mailForm?.subject||''} onChange={e=>mailForm&&setMailForm({...mailForm,subject:e.target.value})}/></label>
     <label className="full">견적 요청 본문<textarea required minLength={10} maxLength={12000} rows={12} value={mailForm?.body||''} onChange={e=>mailForm&&setMailForm({...mailForm,body:e.target.value})}/></label>
    </div>
    <div className="wf-mail-attachment"><Paperclip size={16}/><span>BioFlow_RFQ_{CASE}.csv 자동 첨부 · 생산 일정과 원료/수량은 현재 ERP 데이터 기준</span></div>
    <label className="wf-mail-confirm"><input type="checkbox" checked={mailConfirmed} onChange={e=>setMailConfirmed(e.target.checked)}/><span>발신·수신 주소, 메일 본문, 요청 수량·일정 및 첨부 CSV를 확인했습니다. 이 메일을 실제 외부 주소로 발송합니다.</span></label>
    <div className="wf-modal-actions"><Button type="button" variant="outline" onClick={()=>setModal(null)}>취소</Button><Button type="submit" disabled={!mailSettings?.configured||!mailConfirmed||mailSending||!mailSettings.allowed_senders.includes((mailForm?.sender_email||'').trim().toLowerCase())}>{mailSending?<><RefreshCw className="wf-spin" size={16}/> SMTP 전송 중</>:<><Send size={16}/> 실제 메일 발송</>}</Button></div>
   </form>}
   {modal==='mail-settings'&&<div className="wf-modal-actions"><Button variant="outline" onClick={()=>setModal(null)}>닫기</Button></div>}
   {modal==='mail'&&<section className="wf-mail-outbox"><h3>최근 발송 이력</h3>{mailOutbox.length?<div className="wf-mail-history">{mailOutbox.slice(0,5).map((row,i)=><div key={String(row.id||i)}><b>{String(row.vendor_name||row.vendor_id||'공급업체')} · {String(row.status||'상태 미상')}</b><span>{String(row.recipient||'')} · {String(row.created_at||'')}</span><small>{String(row.subject||'')}</small></div>)}</div>:<p>{mailSettings?'등록된 발송 이력이 없습니다.':'승인자 인증 후 발송 이력이 표시됩니다.'}</p>}</section>}
  </DecisionModal>
 <DecisionModal title="재고 위험 상세 · 최초 알림" open={modal==='risk'} onClose={()=>setModal(null)}>{riskContent}<div className="wf-modal-actions"><Button variant="outline" onClick={()=>{apply(x=>approveInquiry(x,false),'공급 확인을 보류했습니다. 문의는 생성하지 않았습니다.');setModal(null)}}>보류</Button><Button onClick={()=>setModal('first')} disabled={!!s.orders.length}>견적 요청 승인 검토</Button></div></DecisionModal>
 <DecisionModal title="1차 승인 · 공급업체 확인" open={modal==='first'} onClose={()=>setModal(null)}>{riskContent}<div className="wf-approval-scope"><b>이번 승인 범위</b><p>승인된 공급 경로에 제품·수량·입고일·단가·MOQ·분할·품질·지급 조건을 가상 문의하고 발주 검토를 시작합니다. <strong>구매 주문 승인은 포함하지 않습니다.</strong></p></div><div className="wf-modal-actions"><Button variant="outline" onClick={()=>{apply(x=>approveInquiry(x,false),'1차 검토를 보류했습니다.');setModal(null)}}>보류</Button><Button disabled={!!s.orders.length} onClick={()=>{if(apply(x=>approveInquiry(x,true),'1차 승인 완료 · 승인된 조건으로 공급 확인을 시작할 수 있습니다.')){setModal(null);openCase('inquiries')}}}>공급업체 확인 승인</Button></div></DecisionModal>
 <DecisionModal title="2차 승인 · 구매 발주서 생성" open={modal==='final'} onClose={()=>setModal(null)}>{report?.selected&&<><h2>승인한 조건으로 내부 PO를 등록합니다.</h2><dl className="wf-facts"><div><dt>추천 공급업체</dt><dd>{report.selected}</dd></div><div><dt>원료 / 수량</dt><dd>MAT-IL7 / {report.analysis.recommendation?.quantity}바이알</dd></div><div><dt>구매·운송 발주금액</dt><dd>{won(report.analysis.recommendation?.subtotal||0)}</dd></div><div><dt>추가 비용 포함 총비용 예측</dt><dd>{won(report.analysis.recommendation?.total||0)}</dd></div><div><dt>검증 전략</dt><dd>{report.id}</dd></div><div><dt>승인·회신 데이터</dt><dd>R{report.revision} / {stale?'변경 감지':'원본·회신 일치'}</dd></div></dl><p className="wf-note">등록 순간 원본·견적·회신 유효기간·전략 버전을 다시 검증하고 중복 PO를 차단합니다. 실제 주문 전송·결제·업체 수락·QA 사용 승인은 수행하지 않습니다.</p></>}{finalErrors(s).map(x=><p className="wf-warning-text" key={x}>{x}</p>)}<div className="wf-modal-actions"><Button variant="outline" onClick={()=>setModal(null)}>돌아가기</Button><Button disabled={approving||finalErrors(s).length>0} onClick={approveFinal}>{approving?'검증·등록 중…':'최종 승인 · 발주서 생성'}</Button></div></DecisionModal>
 <DecisionModal title="조건 변경 감지 · 재검증 요청" open={modal==='change'} onClose={()=>setModal(null)}><h2>기존 추천은 재검증이 필요합니다.</h2><p>현재 원본 R{s.data.revision} 기준으로 수량·날짜·금액·회신 확약을 다시 계산해야 합니다. 승인 범위가 달라졌다면 1차 승인을 갱신하고, 변경 견적은 공급업체에 가상 재확인합니다.</p><p className="wf-note">기존 분석·승인·PO 스냅샷은 보존합니다. 이전 데이터로 새 PO를 등록할 수 없습니다.</p><div className="wf-modal-actions"><Button variant="outline" onClick={()=>setModal(null)}>현재 업무 계속</Button><Button onClick={()=>{setModal(null);if(s.orders.length){apply(trackReview);setPage('tracking');setDrawer({type:'notifications'});return}openCase(approved?'analysis':'inquiries');if(!approved)setModal('first');else beginAnalysis()}}>재분석 절차 시작</Button></div></DecisionModal>
 <DecisionModal title="입고·QC 위험 경고" open={modal==='delay'} onClose={()=>setModal(null)}><h2>{poLine?.issue||'발주 회차의 사용 가능 조건이 변경됐습니다.'}</h2><dl className="wf-facts"><div><dt>영향 회차</dt><dd>{poLine?.id}</dd></div><div><dt>변경 사용 가능 예상</dt><dd>{poLine?.available}</dd></div><div><dt>생산 부족 합계</dt><dd>{r.shortage}개</dd></div><div><dt>영향 생산</dt><dd>{r.rows.filter(p=>p.shortage).map(p=>p.id).join(', ')||'미래 계획 재확인 필요'}</dd></div></dl><p>새 위험은 해당 납품 Lot와 관련 주문 범위에 적용합니다. QA 보류를 AI가 임의로 해제하거나 기존 주문을 자동 취소하지 않습니다.</p><div className="wf-modal-actions"><Button variant="outline" onClick={()=>setModal(null)}>닫기</Button><Button onClick={()=>{apply(trackReview,'현재 PO·품질·생산 조건으로 대안을 재검토했습니다.');setModal(null);setDrawer({type:'notifications'})}}>AI 재분석 · 대안 검토</Button></div></DecisionModal>
 <DecisionModal title="전체 업무 시연 초기화" open={modal==='reset'} onClose={()=>setModal(null)}><h2>v2.1 업무 기록을 초기화할까요?</h2><p>직접 편집한 값, 두 단계 승인, 공급 문의·회신, 독립 분석, 전략, PO와 후속 검사 기록을 삭제하고 최초 IL-7 기준 데이터로 돌아갑니다.</p><div className="wf-modal-actions"><Button variant="outline" onClick={()=>setModal(null)}>취소</Button><Button variant="danger" onClick={()=>{setRunning(false);setS(detect(seedWorkflow()));setSelectedPO('');setSelectedLine('');setModal(null);setDrawer(null);setPage('inbox');setToast('최초 IL-7 업무 데이터로 초기화했습니다.')}}>초기화 실행</Button></div></DecisionModal>
 <DecisionModal title={'ERP 원본 편집 · '+(edit?.id||'')} open={!!edit} onClose={()=>setEdit(null)}>{edit&&<form onSubmit={e=>{e.preventDefault();submitEdit()}}><div className="wf-edit-form">{Object.entries(edit.values).map(([k,v])=><label key={k}>{fields[k]||k}<input type={dateKeys.has(k)?'date':'number'} min="0" step="1" value={v} aria-label={fields[k]||k} onChange={e=>setEdit({...edit,values:{...edit.values,[k]:e.target.value}})} required/></label>)}</div><p className="wf-note">수량·단가·일정 편집으로 품질 승인이 바뀌지 않습니다. 견적 조건 변경은 기존 공급 회신을 재확인 상태로 전환합니다.</p>{error&&<p className="wf-warning-text" role="alert">{error}</p>}<div className="wf-modal-actions"><Button type="button" variant="outline" onClick={()=>setEdit(null)}>취소</Button><Button type="submit">저장 · 재검증</Button></div></form>}</DecisionModal>
 <Dialog.Root open={!!drawer} modal={false} onOpenChange={open=>!open&&setDrawer(null)}><Dialog.Portal><Dialog.Content className={'wf-drawer '+(drawer?.type==='po'?'po-drawer':'')} onOpenAutoFocus={e=>e.preventDefault()}><header><div><Dialog.Title>{drawer?.type==='notifications'?'알림 센터':drawer?.type==='reply'?'공급업체 회신 상세':drawer?.type==='finding'?'독립 분석 · 참조 데이터':drawer?.type==='po'?'발주서 상세':drawer?.type==='help'?'시연 · 계산 규칙':'업무 객체 상세'}</Dialog.Title><Dialog.Description>{CASE} · 현재 업무를 유지한 채 상세를 확인합니다.</Dialog.Description></div><Dialog.Close aria-label="상세 패널 닫기"><X size={21}/></Dialog.Close></header><div className="wf-drawer-body">
 {drawer?.type==='notifications'&&<><div className="wf-context-actions"><button onClick={()=>setS({...s,notifications:s.notifications.map(n=>({...n,read:true}))})}>모두 읽음</button><button onClick={()=>{setDrawer(null);setModal('risk')}}>부족 상세 · 1차 승인</button></div><div className="wf-notice-list">{s.notifications.map(n=><article key={n.id} className={!n.read?'unread':''}><div><Status tone={n.type==='위험'?'amber':n.type==='회신'?'blue':'normal'}>{n.type}</Status><small>{time(n.at)}</small></div><h3>{n.title}</h3><p>{n.body}</p>{n.type==='회신'&&<button onClick={()=>{const q=s.inquiries.find(q=>q.id===n.ref);if(q)setDrawer({type:'reply',q})}}>회신 원문 보기</button>}{n.type==='위험'&&<button onClick={()=>{setDrawer(null);s.orders.length?go('tracking'):setModal('risk')}}>영향 업무 열기</button>}</article>)}</div></>}
 {drawer?.type==='reply'&&(()=>{const q=s.inquiries.find(q=>q.id===drawer.q.id)||drawer.q;const term=q.terms;return <><div className="wf-drawer-object"><small>{q.id}</small><h2>{q.vendor}업체 · {q.status}</h2><Status tone={replyValid(s,q)?'green':'amber'}>{replyValid(s,q)?'유효 확약':Date.parse(s.now)>Date.parse(q.validUntil)?'회신 만료':'확정 공급 제외'}</Status></div><dl className="wf-facts single"><div><dt>확인 시각</dt><dd>{q.repliedAt?time(q.repliedAt):'미회신'}</dd></div><div><dt>회신 기한</dt><dd>{time(q.deadline)}</dd></div><div><dt>최종 결정 기한 (추정)</dt><dd>{time(q.decisionDue)}</dd></div><div><dt>회신·견적 유효기간</dt><dd>{time(q.validUntil)}</dd></div><div><dt>확약 수량</dt><dd>{term?.shipments.reduce((n,l)=>n+l.quantity,0)||0}바이알</dd></div><div><dt>미확인 조건</dt><dd>{q.missing.join(' / ')||'없음'}</dd></div><div><dt>다음 조치</dt><dd>{replyValid(s,q)?'독립 분석에 전달':Date.parse(s.now)>=Date.parse(q.decisionDue)?'최종 대응 기한 경과 · 긴급/일정 조정':q.status==='공급 불가'?'대체 경로 확인':'누락 조건 재문의 또는 대체 공급 병행'}</dd></div></dl><h3>{q.history.some(h=>h.status==='실제 메일 발송 · 회신 대기')?'실제 메일 발송 기록':'가상 회신 원문'}</h3><pre className="wf-source-message">{q.original}</pre>{term&&<table className="wf-plain-table"><thead><tr><th>회차</th><th>수량</th><th>입고일</th><th>확약 근거</th></tr></thead><tbody>{term.shipments.map(l=><tr key={l.id}><td>{l.id}</td><td>{l.quantity}</td><td>{l.arrival}</td><td>{l.commitment}</td></tr>)}</tbody></table>}<div className="wf-context-actions"><Button variant="outline" disabled={Date.parse(s.now)>=Date.parse(q.decisionDue)||q.attempt>=3||q.status==='대상 제외'} onClick={()=>{const n=apply(x=>followupInquiry(x,q.vendor),'누락 조건을 가상 재문의했습니다.');if(n)setDrawer({type:'reply',q:n.inquiries.find(x=>x.id===q.id)!})}}>누락 조건 재문의 ({q.attempt}/3)</Button><button onClick={()=>{setDrawer(null);openCase('inquiries')}}>업체 전체 비교</button></div><h3>요청·회신 이력</h3><div className="wf-history">{q.history.map((h,i)=><div key={i}><b>{h.status} · {time(h.at)}</b><p>{h.note}</p></div>)}</div></>})()}
 {drawer?.type==='finding'&&<><div className="wf-drawer-object"><small>{drawer.finding.id} / R{drawer.finding.revision}</small><h2>{agents.find(a=>a.id===drawer.finding.agent)?.name}</h2><p>{drawer.finding.result}</p></div><h3>실행된 조회 · 계산 근거</h3>{drawer.finding.evidence.map((e,i)=><section className="wf-evidence" key={i}><small>{e.table} / {e.ids.join(' · ')}</small><code>{e.formula}</code><p>{e.result}</p><button onClick={()=>{setPage(e.table==='inquiries'?'case':e.table==='lots'?'inventory':e.table==='production'?'production':'case');if(e.table==='inquiries')setTab('inquiries');setToast('원본 표의 관련 행을 표시합니다. 분석 결과는 당시 버전 기준입니다.')}}>참조 업무 표 보기</button></section>)}<h3>필수조건 · 미확인 사항</h3><ul>{[...drawer.finding.constraints,...drawer.finding.unknowns].map((x,i)=><li key={i}>{x}</li>)}</ul><h3>공통 JSON 산출물</h3><pre className="wf-source-message">{JSON.stringify({caseId:CASE,strategyId:s.integration?.id||'통합 대기',dataVersion:drawer.finding.revision,author:drawer.finding.agent,alternatives:drawer.finding.alternatives,constraints:drawer.finding.constraints,evidenceRefs:drawer.finding.evidence.map(x=>x.ids),assumptions:drawer.finding.assumptions,unknowns:drawer.finding.unknowns},null,2)}</pre></>}
 {drawer?.type==='po'&&<><div className="wf-context-actions"><Button onClick={()=>window.print()}><Printer size={17}/>발주서 인쇄 / PDF 저장</Button><button onClick={()=>{setSelectedPO(drawer.po.id);setDrawer(null);go('tracking')}}>입고 추적 열기</button></div><PurchaseOrderDocument po={drawer.po}/></>}
 {drawer?.type==='row'&&<RowDetail row={drawer.row} kind={drawer.kind} s={s}/>}
 {drawer?.type==='help'&&<><h2>3–5분 업무 시연</h2><ol className="wf-guide"><li>부족 알림에서 생산 부족10개와 안전 포함 목표12개를 확인하고 1차 공급업체 확인을 승인합니다.</li><li>공급 확인 요청 생성 → 가상 회신 수신. A/B 확약과 C 불확실을 구분합니다.</li><li>Orchestrator가 4개 독립 분석을 배분합니다. 결과를 눌러 조회 행·수식·근거를 보고 추가 검증을 실행합니다.</li><li>최종 B 분할안을 검토하고 2차 승인 → 내부 PO 등록. 발주서를 상세 조회·인쇄합니다.</li><li>입고 추적에서 B 2회차 QC +3일을 적용해 11.12 사용·11.11 부족을 확인하고 대안을 재분석합니다.</li><li>정상 시연은 회차별 출하 → 입고 → QC → QA를 기록하고 생산 투입을 반영합니다. 기존 가용량과 미래 예측을 구분합니다.</li></ol><h3>역산 규칙과 한계</h3><p>고객 납기에서 생산 {downstream.productionDays}일 + 완제품 확인 {downstream.finishedCheckDays}일 + 포장 {downstream.packingDays}일 + 고객 운송 {downstream.transportDays}일을 역산합니다. 모두 합성 가정이며 실제 고객 납기를 보장하지 않습니다.</p><p>공급 회신과 품질 근거는 합성입니다. 규칙 계산·버전 검증·재고 반영은 실제 코드로 동작하고 외부 AI API·메일·결제는 연결하지 않습니다.</p></>}
 </div></Dialog.Content></Dialog.Portal></Dialog.Root>
 {drawer?.type==='po'&&<div className="wf-print-root"><PurchaseOrderDocument po={drawer.po}/></div>}
 {toast&&<div className="wf-toast" role="status">{toast}<button aria-label="알림 닫기" onClick={()=>setToast('')}><X size={17}/></button></div>}
 </div>
}
function RowDetail({row,kind,s}:{row:Row;kind:string;s:Workflow}){let detail:Record<string,unknown>={...row};if(kind==='lots'){const l=s.data.lots.find(l=>l.id===row.id);detail={...detail,보류사유:l?.hold||'없음',해제조건:l?.releaseCondition,CoA:l?.coa,온도:l?.temperature,제품:s.data.products.find(p=>p.id===l?.material)};}if(kind==='quotes'){const v=s.data.vendors.find(v=>v.id===row.id);detail={...detail,계약조건:v?.changeTerms,품질승인:v?.approved&&v?.productApproved?'업체·제품 승인':'미승인',회신상태:s.inquiries.find(q=>q.vendor===row.id)?.status||'아직 문의 안 함'};}const skip=new Set(['tone','fingerprint','sourceStamp','stamp','snapshot','findings','inquiries','history']);return <><div className="wf-drawer-object"><small>{kind}</small><h2>{row.id}</h2></div><dl className="wf-detail-list">{Object.entries(detail).filter(([k])=>!skip.has(k)).map(([k,v])=><div key={k}><dt>{detailLabels[k]||fields[k]||k}</dt><dd>{typeof v==='object'?<pre>{JSON.stringify(v,null,2)}</pre>:String(v??'—')}</dd></div>)}</dl></>}
function PurchaseOrderDocument({po}:{po:PO}){return <article className="wf-po-paper"><div className="wf-po-title"><div><b>BioFlow 제조사업장</b><small>공정개발 · 합성 업무 데이터</small></div><h1>구 매 발 주 서</h1></div><div className="wf-po-ident"><span>발주번호 <strong>{po.id}</strong></span><span>발주일 {po.createdAt.slice(0,10)}</span></div><table className="wf-po-party"><tbody><tr><th>공급업체</th><td>{po.vendor.name}</td><th>발주 담당</th><td>김민서 · 구매팀(가상)</td></tr><tr><th>사업장 / 납품처</th><td>1000 / 원료 입고·품질 구역(합성)</td><th>구매요청</th><td>{po.caseId}</td></tr><tr><th>제품코드</th><td>{po.product.sku}</td><th>원료코드</th><td>{po.product.id}</td></tr><tr><th>제형 / 규격</th><td colSpan={3}>{po.product.form} / {po.product.content} / 단위 {po.product.unit}, 변환계수 {po.product.conversion}</td></tr></tbody></table><table className="wf-po-items"><thead><tr><th>품명</th><th>수량</th><th>단위</th><th>단가</th><th>구매금액</th></tr></thead><tbody><tr><td>{po.product.name}</td><td>{po.quantity}</td><td>바이알</td><td>{won(po.unitPrice)}</td><td>{won(po.purchase)}</td></tr><tr><td colSpan={4}>운송비 · {po.lines.length}회 납품</td><td>{won(po.shipping)}</td></tr><tr className="total"><td colSpan={4}>발주 공급가액 · 구매 + 운송</td><td>{won(po.subtotal)}</td></tr></tbody></table><h3>분할 납품 일정 및 참조</h3><table className="wf-po-items"><thead><tr><th>회차</th><th>수량</th><th>입고일</th><th>QC/QA 사용 가능 예상</th><th>납품 Lot / 근거</th></tr></thead><tbody>{po.lines.map((l,i)=><tr key={l.id}><td>{i+1}</td><td>{l.quantity}바이알</td><td>{l.arrival}</td><td>{l.available}</td><td>{l.lot}<small>{l.commitment}</small></td></tr>)}</tbody></table><dl className="wf-po-terms"><div><dt>지급 조건</dt><dd>회차별 입고일 기준 · 지급일별 현금 한도 검증 / 합성 조건</dd></div><div><dt>납품·변경 조건</dt><dd>{po.vendor.changeTerms}</dd></div><div><dt>품질 조건</dt><dd>승인된 동일 제품·함량·단위, CoA 및 운송 기록 확인. 입고 후 QC 적합과 QA 담당자의 사용 승인이 필요합니다.</dd></div><div><dt>보관 규격</dt><dd>{po.product.storage}</dd></div><div><dt>전략·승인 근거</dt><dd>{po.report} / {po.strategy} / R{po.sourceRevision} / {po.approval}</dd></div></dl><p className="wf-po-disclaimer">본 문서는 내부 ERP 시연용 가상 발주서입니다. 실제 업체 전송·주문 수락·결제·품질 승인이 아닙니다. 부가세는 반영하지 않은 합성 공급가액이며, 시험·보관·폐기처리 총비용 예측 {won(po.estimatedTotal)}은 발주 공급가액과 구분합니다.</p><div className="wf-po-sign"><span>구매 담당자: 김민서(가상)</span><span>최종 발주 승인: {po.approval}</span></div></article>}
const caseColumns:Column[]=[{key:'id',label:'구매요청번호'},{key:'material',label:'원료 코드'},{key:'status',label:'업무 상태'},{key:'priority',label:'위험도'},{key:'shortage',label:'생산 부족',kind:'number'},{key:'target',label:'안전 포함 목표',kind:'number'},{key:'needed',label:'최초 필요일'},{key:'reviewBy',label:'검토 추정기한'},{key:'production',label:'영향 생산'},{key:'owner',label:'담당자'}];
const inquiryColumns:Column[]=[{key:'vendor',label:'업체'},{key:'id',label:'공급 확인번호'},{key:'status',label:'회신 상태'},{key:'unitPrice',label:'단가',kind:'number',format:v=>won(Number(v))},{key:'moq',label:'MOQ',kind:'number'},{key:'quantity',label:'확약 수량',kind:'number'},{key:'arrivals',label:'회차별 입고'},{key:'deadline',label:'회신 기한'},{key:'validUntil',label:'회신 유효기한'},{key:'attempt',label:'문의 횟수',kind:'number'}];
