const strategyColumns:Column[]=[{key:'name',label:'공급 전략'},{key:'kind',label:'전략 구분'},{key:'quantity',label:'실제 주문량',kind:'number'},{key:'unitPrice',label:'단가',kind:'number',format:v=>won(Number(v))},{key:'subtotal',label:'구매·운송 소계',kind:'number',format:v=>won(Number(v))},{key:'total',label:'최종 총비용',kind:'number',format:v=>won(Number(v))},{key:'waste',label:'예상 폐기',kind:'number'},{key:'arrivals',label:'회차별 입고'},{key:'status',label:'필수조건 판정'}];
const poColumns:Column[]=[{key:'id',label:'발주번호'},{key:'material',label:'원료 코드'},{key:'vendorName',label:'공급업체'},{key:'quantity',label:'주문 수량',kind:'number'},{key:'subtotal',label:'발주 공급가액',kind:'number',format:v=>won(Number(v))},{key:'linesCount',label:'입고 회차',kind:'number'},{key:'status',label:'ERP 상태'},{key:'followup',label:'후속 품질'},{key:'approval',label:'2차 승인번호'}];
const trackingColumns:Column[]=[{key:'id',label:'납품 회차'},{key:'status',label:'현재 단계'},{key:'lot',label:'납품 Lot'},{key:'quantity',label:'수량',kind:'number'},{key:'arrival',label:'계획 입고일'},{key:'actualArrival',label:'실제 입고(가상)'},{key:'available',label:'사용 가능 예상'},{key:'qaState',label:'품질 사용 승인'},{key:'issue',label:'지연·품질 이슈'}];
const impactColumns:Column[]=[{key:'id',label:'생산번호'},{key:'date',label:'원료 투입일'},{key:'customer',label:'고객 납기'},{key:'need',label:'필요량',kind:'number'},{key:'before',label:'투입 전 예측',kind:'number'},{key:'shortage',label:'부족량',kind:'number'},{key:'after',label:'투입 후 예측',kind:'number'},{key:'status',label:'영향 판정'}];
const downstreamColumns:Column[]=[{key:'id',label:'생산번호'},{key:'delivery',label:'고객 납기'},{key:'latestInput',label:'역산 최종 투입일'},{key:'date',label:'계획 투입일'},{key:'completion',label:'생산 완료'},{key:'finishedCheck',label:'완제품 확인'},{key:'packing',label:'포장'},{key:'estimatedCustomer',label:'고객 도착 예상'},{key:'status',label:'납기 판정'}];
